/* Constants */
export const PACK_DONE_EVENT = "pack://done" as const;

export const PACK_ERROR_EVENT = "pack://error" as const;

export const PACK_PROGRESS_EVENT = "pack://progress" as const;

/* Types */
/**  Whether AI features can run, and if not, what the user can do. */
export type AiStatus = 
/**  No provider is chosen. */
{ state: "no_provider" } | 
/**  The provider's key is not saved. */
{ state: "key_missing"; 
/**  The provider. */
provider: ProviderId } | 
/**  The OpenAI-compatible server's address is not entered. */
{ state: "base_url_missing" } | 
/**  The entered address is not usable (spec §14.1). */
{ state: "base_url_invalid" } | 
/**  No chat model is chosen. */
{ state: "no_model"; 
/**  The provider. */
provider: ProviderId } | 
/**  Ready. */
{ state: "ready"; 
/**  The provider. */
provider: ProviderId; 
/**  The chat model. */
chat_model: string; 
/**  The tafsir model. */
translation_model: string };

/**  Whether a provider's key is saved. */
export type ApiKeyStatus = {
	/**  The provider. */
	provider: ProviderId,
	/**  Whether its key is in the keychain. */
	saved: boolean,
};

/**  Embedding APIs a vector pack can name. */
export type ApiProvider = 
/**  OpenAI embeddings. */
"openai" | 
/**  Voyage AI embeddings, the provider Anthropic recommends. */
"voyage" | 
/**  Google Gemini embeddings. */
"gemini" | 
/**
 *  An OpenAI-compatible server at a user-entered address (Ollama, LM
 *  Studio); may run on this computer.
 */
"openai_compatible";

/**  Error returned by every command: `{ code, message }` on the frontend. */
export type AppError = {
	/**  Stable code the frontend maps to a translated message. */
	code: AppErrorCode,
	/**  Developer diagnostic in English; never shown to users as-is. */
	message: string,
};

/**
 *  Stable, machine-readable error codes. Renaming a variant is a breaking
 *  change for the frontend's i18n keys.
 */
export type AppErrorCode = 
/**  A database file could not be opened or configured. */
"db_open_failed" | 
/**  Applying a schema migration failed; the database was left unchanged. */
"migration_failed" | 
/**  The database was written by a newer app version than this one. */
"db_version_unsupported" | 
/**  The bundled seed database needed for first launch is missing. */
"seed_missing" | 
/**  A file system operation (copy, backup, directory creation) failed. */
"io_failed" | 
/**  A database query failed. */
"query_failed" | 
/**  The requested item does not exist. */
"not_found" | 
/**  A setting key does not match the allowed key format. */
"invalid_setting_key" | 
/**  A setting value is not valid JSON. */
"invalid_setting_value" | 
/**
 *  Updating the Quran text and bundled translations from the newer bundled
 *  `core.db` failed; the previous data is still in use (spec §6.2).
 */
"core_refresh_failed" | 
/**  A network request failed (offline, timeout, connection reset). */
"network_failed" | 
/**  A request or redirect went to a host outside the allow-list (spec §14.1). */
"host_not_allowed" | 
/**  The server answered a download with an unexpected status or body. */
"download_failed" | 
/**  The pack manifest is not valid JSON or breaks the manifest rules. */
"manifest_invalid" | 
/**  The pack manifest has a `schema_version` this app does not know. */
"manifest_unsupported" | 
/**  No manifest could be fetched and none is cached. */
"manifest_unavailable" | 
/**  The pack type is not supported by this app version. */
"pack_unsupported" | 
/**  The pack needs a newer app version (`min_app_version`). */
"pack_incompatible" | 
/**  Bundled packs cannot be installed or removed; they ship with the app. */
"pack_bundled" | 
/**  The pack is being downloaded or installed right now. */
"pack_busy" | 
/**  The downloaded file does not match the manifest's sha256. */
"pack_hash_mismatch" | 
/**  The pack is larger than the manifest says. */
"pack_too_large" | 
/**  The pack's structure or `pack_info` is not what its manifest entry describes. */
"pack_invalid" | 
/**  The pack names verses the development data lacks; debug builds only. */
"pack_needs_full_data" | 
/**  The pack was built for a content schema this app does not know. */
"pack_schema_unsupported" | 
/**  There is not enough free disk space for the download and installation. */
"disk_space_insufficient" | 
/**  The user cancelled the installation. */
"install_cancelled" | 
/**  The pack's terms must be acknowledged before its first download. */
"terms_not_acknowledged" | 
/**  Installing this morphology pack replaces the installed one and needs confirmation. */
"morphology_replace_required" | 
/**
 *  A request names something that cannot exist: an empty note or title, a
 *  reversed verse range, an unknown citation style.
 */
"invalid_input" | 
/**  The chosen file is not a Siyak backup. */
"backup_invalid" | 
/**  The backup was written by a newer app version than this one. */
"backup_unsupported" | 
/**
 *  Semantic search needs a vector pack with a working embedder (spec §7.4);
 *  `get_semantic_status` says what is missing.
 */
"semantic_unavailable" | 
/**  The OS keychain could not read, save or delete an API key (spec §14.2). */
"keychain_failed" | 
/**  The provider rejected the API key (HTTP 401 or 403). */
"provider_key_rejected" | 
/**  The provider limits requests or the key's quota is used up (HTTP 429). */
"provider_rate_limited" | 
/**  The provider answered with another error or an unexpected response. */
"provider_failed" | 
/**  The provider sent nothing back in time (a thinking model under load). */
"provider_timeout" | 
/**  The model is overloaded (HTTP 503), even after one retry. */
"provider_overloaded" | 
/**
 *  AI features need a provider, a key (or server address) and a model
 *  (spec §8); `get_ai_status` says what is missing.
 */
"ai_unavailable";

/**  An installed audio pack, as the reader's player lists it. */
export type AudioPack = {
	/**  Pack id, e.g. `audio.alafasy`. */
	id: string,
	/**  Title as published (`packs.title`). */
	title: string,
	/**  Title in the interface languages. */
	titles: LocalizedTitle,
	/**  `murattal`, `mujawwad` or `muallim`, if the pack says. */
	style: string | null,
	/**  Attribution shown with the player (spec §6.5). */
	attribution: string | null,
};

/**  A bookmark with its verse. */
export type BookmarkedVerse = {
	/**  The verse with the requested translations. */
	verse: VerseWithTranslations,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	created_at: string,
};

/**  One bundle of the Packs screen and of the first-launch card. */
export type BundleView = {
	/**  Bundle id. */
	id: string,
	/**  Title. */
	title: LocalizedText,
	/**  Description. */
	description: LocalizedText | null,
	/**  Member pack ids. */
	packs: string[],
	/**  Members that are not installed yet (and can be). */
	missing: string[],
	/**  Download size of the missing members. */
	size: number | null,
	/**  Installed size of the missing members. */
	installed_size: number | null,
};

/**  The Packs screen. */
export type Catalog = {
	/**  `remote` or `local`. */
	source: string,
	/**  When the manifest was fetched (milliseconds since the epoch). */
	fetched_at: number | null,
	/**  True if the latest fetch failed and a cached manifest is shown. */
	offline: boolean,
	/**  Why the latest fetch failed. */
	error: AppError | null,
	/**  Packs: manifest order, then installed packs missing from the manifest. */
	packs: PackView[],
	/**  Bundles. */
	bundles: BundleView[],
};

/**  A message of a session. */
export type ChatMessage = {
	/**  Message id. */
	id: number,
	/**  Who wrote it. */
	role: Role,
	/**  Its text; an answer is untrusted model output. */
	content: string,
	/**  The verses an answer cites, in order. */
	cited: VerseCitation[],
	/**  What went into an answer's context. */
	sources: ChatSources | null,
	/**  When it was written (UTC). */
	created_at: string,
};

/**  Something the context lacks, said to the user. */
export type ChatNotice = 
/**  The model may not read Arabic, so Arabic tafsirs were left out. */
{ kind: "arabic_tafsirs_skipped" } | 
/**  A chat tafsir is not installed. */
{ kind: "tafsir_missing"; 
/**  Its pack id. */
pack_id: string };

/**  The end of a chat answer. */
export type ChatReply = {
	/**
	 *  The session the messages were saved in; a new one if none was given.
	 *  `None` only if the answer was stopped before any text arrived.
	 */
	session_id: number | null,
	/**  The saved question. */
	question: ChatMessage | null,
	/**  The saved answer, with its citations and sources. */
	answer: ChatMessage | null,
	/**  Why the answer ended. */
	finish: Finish,
};

/**  A session with its messages, oldest first. */
export type ChatSession = {
	/**  The session. */
	session: ChatSessionSummary,
	/**  Its messages. */
	messages: ChatMessage[],
};

/**  A chat session in the list. */
export type ChatSessionSummary = {
	/**  Session id. */
	id: number,
	/**  Its title: the start of the first message, or the user's. */
	title: string | null,
	/**  The provider of its answers. */
	provider: string,
	/**  The model of its answers. */
	model: string,
	/**  When it started. */
	created_at: string,
	/**  When its last message was written. */
	updated_at: string,
};

/**  What went into the context of an answer, shown as "sources used". */
export type ChatSources = {
	/**  The retrieved verses, best first. */
	verses: SourceVerse[],
	/**  The tafsir passages added. */
	tafsirs: SourceTafsir[],
	/**  What was left out and why. */
	notices: ChatNotice[],
	/**
	 *  The search query the verses were retrieved with, if the model wrote
	 *  one (answers saved before it was recorded have none).
	 */
	search_query?: string | null,
};

/**  What to cite. */
export type CitationRef = 
/**  Verses, with a line for the Quran and one per translation. */
{ kind: "verses"; 
/**  First verse, by global id. */
from: number; 
/**  Last verse, by global id. */
to: number; 
/**  The translations to cite. */
translation_ids: string[] } | 
/**  The commentary of a tafsir on a verse. */
{ kind: "tafsir"; 
/**  Tafsir pack id. */
pack_id: string; 
/**  Global id of the verse. */
verse: number };

/**  A citation style. */
export type CitationStyle = {
	/**  Stable id, the template's file name. */
	id: string,
	/**  Name to show. */
	name: string,
};

/**  A collection with its items in order. */
export type Collection = {
	/**  The collection. */
	summary: CollectionSummary,
	/**  The items in the user's order. */
	items: CollectionItem[],
};

/**  A collection to create (no `id`) or rename. */
export type CollectionInput = {
	/**  The collection to change, or `None` for a new one. */
	id: number | null,
	/**  Title; must not be blank. */
	title: string,
	/**  Markdown description. */
	description: string | null,
};

/**  An item with its content. */
export type CollectionItem = {
	/**  Item id. */
	id: number,
	/**  What the item refers to. */
	item: ItemRef,
	/**  Short note on this item. */
	annotation: string | null,
	/**  The content it refers to. */
	content: ItemContent,
};

/**  A collection without its items. */
export type CollectionSummary = {
	/**  Collection id. */
	id: number,
	/**  Title. */
	title: string,
	/**  Markdown description. */
	description: string | null,
	/**  Number of items. */
	item_count: number,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	created_at: string,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	updated_at: string,
};

/**  A range of verses with the chosen translations and tafsirs (spec §13.3). */
export type Compare = {
	/**
	 *  The verses, at most [`MAX_COMPARE_VERSES`], with translations in the
	 *  requested order.
	 */
	verses: VerseWithTranslations[],
	/**  The tafsirs in the requested order. */
	tafsirs: CompareTafsir[],
};

/**  The commentary of one tafsir on a range of verses. */
export type CompareTafsir = {
	/**  Tafsir pack id. */
	pack_id: string,
	/**
	 *  Passages overlapping the range, in verse order. A passage may begin
	 *  before the range or end after it.
	 */
	passages: TafsirPassage[],
};

/**  Every occurrence of a root or lemma (spec §7.3, §13.3). */
export type Concordance = {
	/**  The root, or the lemma's root. */
	root: RootInfo | null,
	/**  The lemma, when the concordance is narrowed to one. */
	lemma: LemmaInfo | null,
	/**
	 *  The lemmas of the root, most frequent first; for a lemma without a
	 *  root, the lemma alone.
	 */
	lemmas: LemmaInfo[],
	/**  Words listed. */
	occurrences: number,
	/**  Verses containing them. */
	verse_count: number,
	/**  Occurrences per surah, in Mushaf order. */
	by_surah: SurahCount[],
	/**  The requested page of verses, in Mushaf order. */
	verses: ConcordanceVerse[],
};

/**  What a concordance lists. */
export type ConcordanceTarget = 
/**  Every word with this root. */
{ kind: "root"; 
/**  Root id. */
id: number } | 
/**  Every word with this lemma. */
{ kind: "lemma"; 
/**  Lemma id. */
id: number };

/**  A verse of a concordance. */
export type ConcordanceVerse = {
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
	/**  The words of the verse, in order. */
	words: ConcordanceWord[],
	/**  The requested translation, if the verse has one. */
	translation: VerseTranslation | null,
};

/**  A word of a concordance verse. */
export type ConcordanceWord = {
	/**  Uthmani script. */
	text_ar: string,
	/**  Whether this word is what the concordance lists. */
	matched: boolean,
};

/**  The core data in use and whether refreshing it failed at startup (spec §6.2). */
export type CoreStatus = {
	/**  `content_meta.core_version` of the content database. */
	core_version: number,
	/**  Which dataset a debug build loaded (`dev` or `full`); `None` in release builds. */
	seed: string | null,
	/**  Why the core refresh failed, if it did; the previous data is still in use. */
	refresh_error: AppError | null,
};

/**  What an action is estimated to cost before the user confirms it. */
export type CostEstimate = {
	/**  Estimated input tokens. */
	input_tokens: number,
	/**  Estimated output tokens. */
	output_tokens: number,
	/**  Estimated cost in USD; `None` if the model's price is unknown. */
	cost_usd: number | null,
	/**  The provider of the model. */
	provider: ProviderId,
	/**  The model. */
	model: string,
	/**
	 *  Whether this would pass the monthly limit (spec §9.4): the interface
	 *  asks for confirmation, it does not block.
	 */
	over_limit: boolean,
};

/**  What a logged request was for. */
export type Feature = 
/**  A chat answer. */
"chat" | 
/**  A tafsir summary or translation. */
"translate";

/**  Why an answer ended. */
export type Finish = 
/**  The model finished. */
"complete" | 
/**  The answer reached `max_tokens`. */
"truncated" | 
/**  The user stopped it. */
"cancelled";

/**  What the Find screen found for a question. */
export type FoundVerses = {
	/**  The search sentence the chat model wrote from the question, if it did. */
	search_query: string | null,
	/**  The verses closest in meaning, best first. */
	verses: RelatedVerse[],
	/**  Whether the rewrite was stopped; nothing was searched then. */
	cancelled: boolean,
};

/**  How an import treats what is already there. */
export type ImportMode = 
/**  Keep everything and add what is new. Importing the same file twice adds nothing. */
"merge" | 
/**  Delete bookmarks, notes, collections and the translation cache first. */
"replace";

/**  What an import did. */
export type ImportReport = {
	/**  Bookmarks added. */
	bookmarks: number,
	/**  Notes added. */
	notes: number,
	/**  Collections added. */
	collections: number,
	/**  Collection items added, also to collections that already existed. */
	items: number,
	/**  Tafsir translations added. */
	tafsir_translations: number,
	/**  Entries left out: unknown verses, tafsirs that are not installed, unreadable items. */
	skipped: number,
};

/**
 *  Why a query that looks like a verse reference leads nowhere. The values are
 *  the `command_palette.errors` keys of the interface.
 */
export type InvalidReference = 
/**  There are 114 surahs. */
"surah_out_of_range" | 
/**  The surah has no such verse, or the range is reversed. */
"ayah_out_of_range";

/**  The content an item refers to, as it is now. */
export type ItemContent = 
/**  The verses, with the requested translations. */
{ kind: "verse_range"; 
/**  The verses in order. */
verses: VerseWithTranslations[] } | 
/**  The note, unless it has gone. */
{ kind: "note"; 
/**  The note. */
note: Note | null } | 
/**  The root, if the installed morphology pack has it. */
{ kind: "root"; 
/**  The root. */
root: RootInfo | null } | 
/**  The lemma, if the installed morphology pack has it. */
{ kind: "lemma"; 
/**  The lemma. */
lemma: LemmaInfo | null } | 
/**  The commentary, if the pack is installed and covers the verse. */
{ kind: "tafsir"; 
/**  The verse the item was added on. */
verse: VerseRef | null; 
/**  The tafsir pack. */
tafsir: TafsirInfo | null; 
/**  The passage covering the verse. */
passage: TafsirPassage | null };

/**
 *  What a collection item refers to. Stored in `collection_items` as `kind`
 *  and `ref_json` (the other fields), e.g. `{"from":262,"to":263}` (spec §5.5).
 */
export type ItemRef = 
/**  A verse or a range of verses, by global id. */
{ kind: "verse_range"; 
/**  First verse. */
from: number; 
/**  Last verse. */
to: number } | 
/**  One of the user's notes. */
{ kind: "note"; 
/**  Note id. */
id: number } | 
/**  A root, e.g. `ر ح م`. */
{ kind: "root"; 
/**  Root text. */
root: string } | 
/**  A lemma, as in the morphology pack. */
{ kind: "lemma"; 
/**  Lemma text. */
lemma: string } | 
/**  The commentary of a tafsir on a verse. */
{ kind: "tafsir"; 
/**  Tafsir pack id. */
pack_id: string; 
/**  Global id of the verse. */
verse: number };

/**  What the app is doing with a pack right now. */
export type JobView = 
/**  Waiting for an earlier job. */
{ state: "queued" } | 
/**  Downloading, verifying or installing. */
{ state: "running"; 
/**  Current phase. */
phase: Phase; 
/**  Bytes done in this phase. */
done: number | null; 
/**  Bytes in this phase. */
total: number | null };

/**  A lemma and how many words have it. */
export type LemmaInfo = {
	/**  Lemma id. */
	id: number,
	/**  As in the source, including a trailing homograph digit (`عَاد2`). */
	lemma: string,
	/**  Words with this lemma. */
	occurrences: number,
};

/**  A `{ "tr": [...], "en": [...] }` list, e.g. `license_terms`. */
export type LocalizedList = {
	/**  Turkish items. */
	tr: string[],
	/**  English items. */
	en: string[],
};

/**  A `{ "tr", "en" }` text. */
export type LocalizedText = {
	/**  Turkish. */
	tr: string,
	/**  English. */
	en: string,
};

/**  The title of a pack in the interface languages, where the pack provides one. */
export type LocalizedTitle = {
	/**  Turkish title. */
	tr: string | null,
	/**  English title. */
	en: string | null,
};

/**  The interface's words for the Markdown file. */
export type MarkdownLabels = {
	/**  Interface language: picks the surah names and pack titles. */
	language: string,
	/**  Heading of the notes under a verse. */
	notes: string,
	/**  Heading of the bibliography. */
	bibliography: string,
	/**  Label of a root item. */
	root: string,
	/**  Label of a lemma item. */
	lemma: string,
	/**  Label of the occurrence count. */
	occurrences: string,
	/**  Label of the data source of a root or lemma. */
	source: string,
	/**  Shown for an item whose pack is not installed. */
	unavailable: string,
	/**  Label of the Quran text source in the bibliography. */
	quran_text: string,
};

/**  A model a provider offers. */
export type ModelInfo = {
	/**  The id sent in requests. */
	id: string,
	/**  A display name, if the provider gives one. */
	name: string | null,
};

/**  The installed morphology pack (spec §5.3.1: its source is shown with the data). */
export type MorphologyPack = {
	/**  Pack id, e.g. `morphology.qac`. */
	id: string,
	/**  Who to credit, e.g. `Quranic Arabic Corpus (corpus.quran.com)`. */
	source: string,
};

/**  One connection log entry (spec §14.1): no URL path, query or content. */
export type NetworkLogEntry = {
	/**  Host name the request went to. */
	host: string,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	at: string,
	/**  Why the request was made, e.g. `manifest` or `pack`. */
	purpose: string,
	/**  HTTP status, or `None` if no response arrived. */
	status: number | null,
	/**  Response body bytes received (a float: 64-bit integers do not cross IPC). */
	bytes: number | null,
};

/**  A note on a verse or a range of verses. */
export type Note = {
	/**  Note id. */
	id: number,
	/**  Global id of the first verse. */
	verse_from: number,
	/**  Global id of the last verse; the same as `verse_from` for a single verse. */
	verse_to: number,
	/**  The first verse. */
	from: VerseRef,
	/**  The last verse. */
	to: VerseRef,
	/**  Markdown. */
	body: string,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	created_at: string,
	/**  UTC time, `YYYY-MM-DDTHH:MM:SSZ`. */
	updated_at: string,
};

/**  A note to create (no `id`) or replace. */
export type NoteInput = {
	/**  The note to replace, or `None` for a new one. */
	id: number | null,
	/**  Global id of the first verse. */
	verse_from: number,
	/**  Global id of the last verse. */
	verse_to: number,
	/**  Markdown; must not be blank. */
	body: string,
};

/**  A pack was installed. */
export type PackDone = {
	/**  Pack id. */
	id: string,
	/**  The morphology pack it replaced, if any. */
	replaced: string | null,
};

/**  The embedding model behind a vector pack, for display. */
export type PackEmbedding = {
	/**  The API that embeds queries; `None` when they are embedded on this computer. */
	provider: ApiProvider | null,
	/**  The model: the API's model id, or the local model's name. */
	model: string,
};

/**  A job failed or was cancelled (`install_cancelled`). */
export type PackFailed = {
	/**  Pack id. */
	id: string,
	/**  Why. */
	error: AppError,
};

/**  A job was queued or moved on. */
export type PackProgress = {
	/**  Pack id. */
	id: string,
	/**  The job's state. */
	job: JobView,
};

/**  One row of the Packs screen. */
export type PackView = {
	/**  Pack id. */
	id: string,
	/**  Pack type (`translation`, `tafsir`, `morphology`, …). */
	kind: string,
	/**  Language of the content. */
	lang: string | null,
	/**  Title in the interface languages. */
	title: LocalizedTitle,
	/**  English title, the fallback. */
	title_fallback: string,
	/**  Description in the interface languages. */
	description: LocalizedText | null,
	/**  Author. */
	author: string | null,
	/**  Version in the manifest, or the installed one if the pack is not in it. */
	version: string,
	/**  Download size in bytes. */
	size: number | null,
	/**  Installed size in bytes. */
	installed_size: number | null,
	/**  License name. */
	license: string,
	/**  Terms shown before download. */
	license_terms: LocalizedList,
	/**  Attribution. */
	attribution: string | null,
	/**  Citation fields. */
	citation: { [key in string]: string },
	/**  Link to the source (`citation.url`). */
	source_url: string | null,
	/**  Oldest app version that can use the pack. */
	min_app_version: string,
	/**  Whether the manifest lists the pack. */
	in_manifest: boolean,
	/**  Whether this app can install packs of this type. */
	supported: boolean,
	/**  Whether the pack is installed. */
	installed: boolean,
	/**  The installed version. */
	installed_version: string | null,
	/**  Whether the manifest has a newer version than the installed one. */
	update_available: boolean,
	/**  Whether the pack needs a newer app. */
	incompatible: boolean,
	/**  Whether the pack ships with the app (cannot be installed or removed). */
	bundled: boolean,
	/**  Whether the terms must be confirmed before download. */
	terms_ack_required: boolean,
	/**  Whether the user confirmed the terms of this version. */
	terms_acknowledged: boolean,
	/**  The installed morphology pack this one would replace. */
	replaces: string | null,
	/**  Packs installed with this one (a vector pack's model pack). */
	requires: string[],
	/**  The running or queued job for this pack. */
	job: JobView | null,
	/**  Where a vector pack embeds queries; `None` for other packs. */
	embedding: PackEmbedding | null,
	/**
	 *  An audio pack's recitation style (`murattal`, `mujawwad` or `muallim`);
	 *  `None` for other packs.
	 */
	style: string | null,
};

/**  Phases of a pack job. */
export type Phase = 
/**  Downloading (or copying from a local source). */
"download" | 
/**  Checking the sha256. */
"verify" | 
/**  Decompressing, checking and copying rows. */
"install";

/**
 *  A provider whose key may be saved: every embedding API ([`ApiProvider`])
 *  plus Anthropic, which offers chat models but no embeddings.
 */
export type ProviderId = 
/**  Anthropic (Claude), chat only. */
"anthropic" | 
/**  OpenAI. */
"openai" | 
/**  Voyage AI, embeddings only. */
"voyage" | 
/**  Google Gemini. */
"gemini" | 
/**  An OpenAI-compatible server at a user-entered address. */
"openai_compatible";

/**  What a query is (spec §7.1). */
export type QueryClass = 
/**  Nothing to search for. */
{ kind: "empty" } | 
/**  A verse or range to jump to: no search. */
{ kind: "reference"; 
/**  Surah number. */
surah: number; 
/**  First verse; `None` for a whole surah. */
ayah: number | null; 
/**  Last verse of a range. */
ayah_to: number | null } | 
/**  A verse reference that does not exist. */
{ kind: "invalid_reference"; 
/**  Why. */
reason: InvalidReference } | 
/**  Arabic letters: searched in the Arabic text. */
{ kind: "arabic" } | 
/**  A root in Latin script, e.g. `s-b-r`. */
{ kind: "latin_root" } | 
/**  Any other text: searched in the translations. */
{ kind: "text" };

/**  A verse found by meaning or by shared roots. */
export type RelatedVerse = {
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
	/**  Uthmani script. */
	text_ar: string,
	/**  The requested translation, if the verse has one. */
	translation: VerseTranslation | null,
	/**
	 *  The shared roots and dictionary forms, rarest first; empty for verses
	 *  related by meaning.
	 */
	shared: SharedTerm[],
};

/**  Where a surah was revealed. */
export type RevelationType = 
/**  Revealed in Mecca. */
"meccan" | 
/**  Revealed in Medina. */
"medinan";

/**  Who wrote a message. */
export type Role = 
/**  The user. */
"user" | 
/**  The model. */
"assistant";

/**  A root and how many words have it. */
export type RootInfo = {
	/**  Root id. */
	id: number,
	/**  Spaced Arabic letters, e.g. `ر ح م`. */
	root: string,
	/**  Words with this root. */
	occurrences: number,
};

/**  Roots and lemmas matching a query. */
export type RootSearch = {
	/**  Matching roots, most frequent first. */
	roots: RootInfo[],
	/**  Matching lemmas, most frequent first. */
	lemmas: LemmaInfo[],
};

/**  Limits on the verses searched (spec §7.2). */
export type SearchFilters = {
	/**  First surah. */
	surah_from: number | null,
	/**  Last surah. */
	surah_to: number | null,
	/**  Meccan or Medinan surahs only. */
	revelation: RevelationType | null,
};

/**  One result: a verse, or one translation of it. */
export type SearchHit = {
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
	/**  The translation pack; `None` for the Arabic text. */
	pack_id: string | null,
	/**  The text with its matches marked: never markup. */
	parts: TextPart[],
};

/**  The results of a search. */
export type SearchResults = {
	/**  How many results there are in all. */
	total: number,
	/**  The best results, up to the limit. */
	hits: SearchHit[],
};

/**  What to search. */
export type SearchScope = 
/**  The Arabic text (`verses_fts`). */
"arabic" | 
/**  The translations (`translations_fts`). */
"translations";

/**  Which part of its word a segment is. */
export type SegmentKind = 
/**  Before the stem. */
"prefix" | 
/**  The stem. */
"stem" | 
/**  After the stem. */
"suffix";

/**  Why semantic features are, or are not, available. */
export type SemanticStatus = 
/**  No vector pack is installed. */
{ state: "no_vector_pack" } | 
/**  The metadata of `pack` is not valid. */
{ state: "invalid"; 
/**  The vector or model pack with the bad metadata. */
pack: string } | 
/**  The model pack the local vector pack needs is not installed. */
{ state: "model_pack_missing"; 
/**  The vector pack. */
pack: string; 
/**  The model pack to install. */
model_pack: string } | 
/**  The model pack embeds into a different space than the vectors. */
{ state: "mismatch"; 
/**  The vector pack. */
pack: string; 
/**  The installed model pack. */
model_pack: string } | 
/**  The provider's API key is not stored. */
{ state: "key_missing"; 
/**  The vector pack. */
pack: string; 
/**  The provider whose key is needed. */
provider: ApiProvider } | 
/**  The address of the OpenAI-compatible server is not entered. */
{ state: "base_url_missing"; 
/**  The vector pack. */
pack: string } | 
/**
 *  The entered address is not usable: not HTTP(S), plain HTTP to another
 *  computer, or with credentials in it (spec §14.1).
 */
{ state: "base_url_invalid"; 
/**  The vector pack. */
pack: string } | 
/**  This app version cannot run the pack's backend yet. */
{ state: "not_built"; 
/**  The vector pack. */
pack: string; 
/**  `local`, `api` or `dev`. */
backend: string } | 
/**  Semantic features work. */
{ state: "ready"; 
/**  The vector pack. */
pack: string; 
/**  The provider queries are sent to; `None` if they stay on this computer. */
provider: ApiProvider | null };

/**  A root or dictionary form two verses share. */
export type SharedTerm = {
	/**  Its concordance. */
	target: ConcordanceTarget,
	/**  The root (`ر ح م`) or dictionary form, in Arabic letters. */
	text: string,
};

/**  A tafsir passage, or the paragraphs of it that fit. */
export type SourceTafsir = {
	/**  Tafsir pack. */
	pack_id: string,
	/**  Its title. */
	title: string,
	/**  The passage (`tafsir.id`). */
	tafsir_id: number,
	/**  First verse it covers. */
	verse_from: VerseRef,
	/**  Last verse it covers. */
	verse_to: VerseRef,
	/**  The paragraphs used, in order. */
	paragraphs: number[],
	/**  Whether every paragraph was used. */
	complete: boolean,
};

/**  A retrieved verse. */
export type SourceVerse = {
	/**  Global verse id. */
	verse_id: number,
	/**  Surah and verse number. */
	verse: VerseRef,
	/**  Similarity to the question. */
	score: number | null,
};

/**  A row of the `surahs` table. */
export type Surah = {
	/**  Surah number, 1..=114. */
	number: number,
	/**  Arabic name. */
	name_ar: string,
	/**  Turkish name. */
	name_tr: string,
	/**  English transliteration of the name. */
	name_en: string,
	/**  Where the surah was revealed. */
	revelation_type: RevelationType,
	/**  Number of verses in the surah. */
	ayah_count: number,
	/**
	 *  Tanzil's basmala, shown as the surah header; `None` for surah 1 (where
	 *  it is verse 1) and surah 9 (spec §5.1).
	 */
	bismillah: string | null,
};

/**  Occurrences within one surah. */
export type SurahCount = {
	/**  Surah number. */
	surah: number,
	/**  Words in this surah. */
	occurrences: number,
};

/**  An installed tafsir pack. */
export type TafsirInfo = {
	/**  Pack id, e.g. `ar.jalalayn`. */
	id: string,
	/**  Title as published (`packs.title`). */
	title: string,
	/**  Title in the interface languages, from the pack's metadata. */
	titles: LocalizedTitle,
	/**  Author of the work. */
	author: string | null,
	/**  BCP 47 language of the text, used for the `lang` attribute. */
	lang: string | null,
	/**  Writing direction of the text, used for the `dir` attribute. */
	dir: TextDirection,
	/**  Attribution that must stay visible with the text (spec §6.5). */
	attribution: string | null,
	/**  Whether the pack has the author's introduction (spec §5.2). */
	has_introduction: boolean,
};

/**  One paragraph of a tafsir passage. */
export type TafsirParagraph = {
	/**  Position within the passage, from 0. */
	idx: number,
	/**
	 *  Text in the small HTML subset of spec §5.2; untrusted, the interface
	 *  renders only the allowed elements.
	 */
	text: string,
	/**  Volume of the printed edition, if known. */
	part: string | null,
	/**  Page of the printed edition, if known. */
	page: number | null,
};

/**  A tafsir passage: commentary on a range of verses, or the introduction. */
export type TafsirPassage = {
	/**  Passage id in `content.db`. */
	id: number,
	/**  First verse covered. */
	verse_from: VerseRef,
	/**  Last verse covered. */
	verse_to: VerseRef,
	/**  Paragraphs in order. */
	paragraphs: TafsirParagraph[],
};

/**  A saved summary or translation, shown next to its original. */
export type TafsirTranslation = {
	/**  The translated paragraph; `None` for a summary of the passage. */
	paragraph_idx: number | null,
	/**  Summary or translation. */
	mode: TranslationMode,
	/**  The interface language it is in. */
	target_lang: string,
	/**  Plain text, untrusted model output. */
	text: string,
	/**  The provider that wrote it. */
	provider: string,
	/**  The model that wrote it. */
	model: string,
	/**  When it was made (UTC). */
	created_at: string,
};

/**  Writing direction of a text block. */
export type TextDirection = 
/**  Left to right. */
"ltr" | 
/**  Right to left. */
"rtl";

/**  A piece of a result's text. */
export type TextPart = {
	/**  The text. */
	text: string,
	/**  Whether it matched the query. */
	matched: boolean,
};

/**  The end of a tafsir summary or translation. */
export type TranslateResult = {
	/**  The saved text; `None` if the user stopped it. */
	translation: TafsirTranslation | null,
	/**  Why it ended: a truncated text is saved as it is. */
	finish: Finish,
};

/**  An installed translation pack. */
export type TranslationInfo = {
	/**  Pack id, e.g. `en.pickthall`. */
	id: string,
	/**  Title as published (`packs.title`). */
	title: string,
	/**  Title in the interface languages, from the pack's metadata. */
	titles: LocalizedTitle,
	/**  BCP 47 language of the translation, used for the `lang` attribute. */
	lang: string | null,
	/**  Writing direction of the translation's language, used for the `dir` attribute. */
	dir: TextDirection,
	/**  Whether the pack ships with the app (`core.db`). */
	bundled: boolean,
};

/**  A summary of the passage or a translation of one paragraph (spec §9.1). */
export type TranslationMode = 
/**  A short summary of the whole passage. */
"summary" | 
/**  A translation of one paragraph. */
"full";

/**  The period of a spending summary. */
export type UsagePeriod = 
/**  The current calendar month (UTC). */
"month" | 
/**  Everything logged. */
"total";

/**  Spending on one feature with one model. */
export type UsageRow = {
	/**  The feature. */
	feature: Feature,
	/**  The provider, as stored. */
	provider: string,
	/**  The model. */
	model: string,
	/**  Number of requests. */
	requests: number,
	/**  Input tokens. */
	input_tokens: number,
	/**  Output tokens. */
	output_tokens: number,
	/**  Known cost in USD; `None` if no request had a known price. */
	cost_usd: number | null,
	/**  Requests whose price was unknown. */
	unpriced: number,
};

/**  Spending in a period (Settings → AI → Spending). */
export type UsageSummary = {
	/**  The known cost of all requests, in USD. */
	total_usd: number | null,
	/**  Per feature and model, most expensive first. */
	rows: UsageRow[],
	/**  The monthly limit, if one is set. */
	monthly_limit_usd: number | null,
};

/**  Sizes of `content.db` before and after compacting, in bytes. */
export type VacuumSizes = {
	/**  Before. */
	before: number | null,
	/**  After. */
	after: number | null,
};

/**  A verse the answer cites. */
export type VerseCitation = {
	/**  Global verse id. */
	verse_id: number,
	/**  Surah and verse number. */
	verse: VerseRef,
};

/**  A range of global verse ids. */
export type VerseIdRange = {
	/**  First verse. */
	from: number,
	/**  Last verse. */
	to: number,
};

/**  A verse by its surah and number. */
export type VerseRef = {
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
};

/**  One translation of a verse. */
export type VerseTranslation = {
	/**  Translation pack id, e.g. `en.pickthall`. */
	pack_id: string,
	/**  BCP 47 language of the translation, used for the `lang` attribute. */
	lang: string | null,
	/**  Translated text. */
	text: string,
};

/**  A verse with its Arabic text and the requested translations. */
export type VerseWithTranslations = {
	/**  Global verse id, 1..=6236. */
	id: number,
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
	/**  Juz (part) number, 1..=30. */
	juz: number,
	/**  Uthmani script for display. */
	text_uthmani: string,
	/**
	 *  Translations in the order they were requested; packs without a row
	 *  for this verse are omitted.
	 */
	translations: VerseTranslation[],
	/**
	 *  The words of the verse, in order: filled by [`get_verses`] when a
	 *  morphology pack is installed, so the reader renders them all at once.
	 */
	words: VerseWord[],
};

/**
 *  One word of a verse. The words of a verse, joined by spaces, are its
 *  `text_uthmani` (the pack's alignment gate checks this).
 */
export type VerseWord = {
	/**  Global word id. */
	id: number,
	/**  Position in the verse, from 1. */
	position: number,
	/**  Uthmani script; two tokens for the four words merged by the alignment. */
	text_ar: string,
};

/**  A word with its full analysis (spec §7.5). */
export type WordDetail = {
	/**  Global word id. */
	id: number,
	/**  Surah number. */
	surah: number,
	/**  Verse number within the surah. */
	ayah: number,
	/**  Position in the verse, from 1. */
	position: number,
	/**  Uthmani script. */
	text_ar: string,
	/**  Transliteration, if the pack has one. */
	translit: string | null,
	/**  English meaning, if the pack has one. */
	gloss_en: string | null,
	/**  Its segments, in order. */
	segments: WordSegment[],
};

/**
 *  One grammatical feature of a segment; both are the pack's stable codes
 *  (`siyak-data/docs/pack-format.md` §7).
 */
export type WordFeature = {
	/**  Feature key, e.g. `case`. */
	key: string,
	/**  Feature value, e.g. `GEN`. */
	value: string,
};

/**  A prefix, stem or suffix of a word. */
export type WordSegment = {
	/**  Prefix, stem or suffix. */
	kind: SegmentKind,
	/**  The segment in Arabic. */
	text_ar: string,
	/**  Part-of-speech tag, e.g. `N`. */
	pos: string,
	/**  Its root, if it has one. */
	root: RootInfo | null,
	/**  Its lemma, if it has one. */
	lemma: LemmaInfo | null,
	/**  Its features, sorted by key. */
	features: WordFeature[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

